H.background();
const v = H.plot2d({ xMin: 0, xMax: 8, yMin: 0, yMax: 22 });
v.grid(); v.axes();
const F = P.F, vel = P.vel;
// Power delivered by a constant force on an object moving at speed vel: P = F * v
const power = F * vel;
// Work done grows linearly with time: W = power * time, sampled across the window.
v.fn(x => power * x, { color: H.colors.accent, width: 3 });
// Sweep a probe that loops across the time window (0..8 s), riding the W(t) line.
const ts = (t % 8);
const Wnow = power * ts;
v.dot(ts, Math.min(Wnow, 22), { r: 6, fill: H.colors.warn });
v.line(ts, 0, ts, Math.min(Wnow, 22), { color: H.colors.violet, width: 1.5, dash: [4, 4] });
// Force arrow on a little cart at the bottom showing F pushing it along.
const cartX = v.X(ts), cartY = v.Y(0.6);
H.arrow(cartX, cartY, cartX + 18 + F * 4, cartY, { color: H.colors.good, width: 3 });
H.text("Power: P = F · v   (W = P · t)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("F = " + F.toFixed(0) + " N   v = " + vel.toFixed(1) + " m/s   →   P = " + power.toFixed(1) + " W", 24, 52, { color: H.colors.sub, size: 13 });
H.text("t = " + ts.toFixed(1) + " s   W = " + Wnow.toFixed(1) + " J", v.box.x + v.box.w - 150, 70, { color: H.colors.good, size: 13 });
H.legend([{ label: "work W = P·t", color: H.colors.accent }, { label: "force F", color: H.colors.good }], H.W - 170, 28);
